        "O-C1": { ja: "\u5165\u9000\u793E\u624B\u7D9A\u304D\u306E\u9032\u884C\u7BA1\u7406\u3068\u78BA\u8A8D", en: "Managing and reviewing onboarding/offboarding" },
        "O-C2": { ja: "\u8907\u6570\u5E97\u8217\u306E\u7D50\u679C\u3001\u5DEE\u7570\u3001\u4F8B\u5916\u3092\u78BA\u8A8D\u3057\u3066\u627F\u8A8D\u53EF\u80FD\u306A\u72B6\u614B\u306B\u3059\u308B", en: "Reviewing results, differences and exceptions across stores and getting them ready for approval" },
        "O-C3": { ja: "\u30C1\u30C3\u30D7\u60C5\u5831\u306E\u5DEE\u3057\u623B\u3057\u72B6\u6CC1\u306E\u78BA\u8A8D\u3068\u3001Payroll \u3078\u306E\u3064\u306A\u304E\uFF08\u8A08\u7B97\u306E\u3084\u308A\u76F4\u3057\u306F\u6C42\u3081\u306A\u3044\uFF09", en: "Checking tip information returned to stores and connecting it to payroll (not re-doing calculations)" },
        "O-C4": { ja: "\u5065\u5EB7\u4FDD\u967A\u306E\u52A0\u5165\u30FB\u5909\u66F4\u30FB\u7D42\u4E86\u306E\u9032\u6357\u3068\u5B8C\u4E86\u306E\u7BA1\u7406", en: "Tracking health insurance enrollments, changes and terminations to completion" },
