        "O-A3": { ja: "\u6A29\u9650\u306E\u7BC4\u56F2\u3092\u5B88\u308A\u3001\u7D66\u4E0E\u30FB\u500B\u4EBA\u60C5\u5831\u3092\u9069\u5207\u306B\u6271\u3044\u3001\u627F\u8A8D\u30FB\u5909\u66F4\u306E\u8A18\u9332\u3092\u6B8B\u3059", en: "Staying within authority, handling payroll and personal data properly, recording approvals and changes" },
        "O-A4": { ja: "\u5E97\u8217\u30FB\u5F93\u696D\u54E1\u3078\u306E\u6848\u5185\u3068\u3001\u4E0D\u5099\u306E\u9023\u7D61\u30FB\u8ABF\u6574\uFF08\u5BFE\u5FDC\u30FB\u671F\u9650\u30FB\u76F8\u8AC7\u5148\u3092\u6DFB\u3048\u308B\uFF09", en: "Guidance and coordination with stores and staff on problems (with action, deadline and contact)" },
        "O-A5": { ja: "\u554F\u984C\u306E\u5171\u6709\u3001\u62C5\u5F53\u306E\u5883\u754C\u306E\u5F15\u7D99\u304E\u78BA\u8A8D\u3001\u5916\u90E8\u62C5\u5F53\u8005\u3068\u306E\u9023\u643A", en: "Sharing problems, confirming handoffs between owners, working with outside partners" },
        "O-B2": { ja: "\u30A4\u30F3\u30DC\u30A4\u30B9\u5165\u529B\u306E\u78BA\u8A8D\uFF08Akane \u3055\u3093\u306E\u5165\u529B\u306E\u30C1\u30A7\u30C3\u30AF\uFF09\u3068\u4F8B\u5916\u5BFE\u5FDC", en: "Reviewing invoice entry (checking Akane's entries) and handling exceptions" },
        "O-B3": { ja: "\u30A4\u30F3\u30DC\u30A4\u30B9\u306E\u5DEE\u7570\u30FB\u4F8B\u5916\u306E\u78BA\u8A8D\u3068\u89E3\u6D88", en: "Reviewing and resolving invoice differences and exceptions" },
        "O-B4": { ja: "\u652F\u6255\u4E88\u5B9A\u30FB\u627F\u8A8D\u72B6\u6CC1\u30FB\u5B9F\u884C\u7D50\u679C\u306E\u7BA1\u7406\uFF08\u9001\u91D1\u6A29\u9650\u306E\u4ED8\u4E0E\u3067\u306F\u306A\u3044\uFF09", en: "Managing payment schedule, approvals and results (not authority to send money)" },
        "O-B5": { ja: "\u30C7\u30A4\u30EA\u30FC\u30BB\u30FC\u30EB\u30B9\u306E\u5DEE\u7570\u30FB\u7570\u5E38\u306E\u78BA\u8A8D\u3068\u5831\u544A", en: "Reviewing and reporting daily sales differences and anomalies" },
        "O-C1": { ja: "\u5165\u9000\u793E\u624B\u7D9A\u304D\u306E\u9032\u884C\u7BA1\u7406\u3068\u78BA\u8A8D", en: "Managing and reviewing onboarding/offboarding" },
        "O-C2": { ja: "\u8907\u6570\u5E97\u8217\u306E\u7D50\u679C\u3001\u5DEE\u7570\u3001\u4F8B\u5916\u3092\u78BA\u8A8D\u3057\u3066\u627F\u8A8D\u53EF\u80FD\u306A\u72B6\u614B\u306B\u3059\u308B", en: "Reviewing results, differences and exceptions across stores and getting them ready for approval" },
        "O-C3": { ja: "\u30C1\u30C3\u30D7\u60C5\u5831\u306E\u5DEE\u3057\u623B\u3057\u72B6\u6CC1\u306E\u78BA\u8A8D\u3068\u3001Payroll \u3078\u306E\u3064\u306A\u304E\uFF08\u8A08\u7B97\u306E\u3084\u308A\u76F4\u3057\u306F\u6C42\u3081\u306A\u3044\uFF09", en: "Checking tip information returned to stores and connecting it to payroll (not re-doing calculations)" },
        "O-C4": { ja: "\u5065\u5EB7\u4FDD\u967A\u306E\u52A0\u5165\u30FB\u5909\u66F4\u30FB\u7D42\u4E86\u306E\u9032\u6357\u3068\u5B8C\u4E86\u306E\u7BA1\u7406", en: "Tracking health insurance enrollments, changes and terminations to completion" },
        "O-C5": { ja: "TDI \u306E\u7533\u8ACB\u652F\u63F4\u3068\u9032\u6357\u7BA1\u7406", en: "Supporting TDI claims and tracking progress" },
